<?php require '../config/conexion.php';require '../config/funciones.php';admin();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM denuncias WHERE id=?");$s->execute([$id]);$d=$s->fetch();if(!$d)exit('No existe');if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$st=$_POST['estatus'];$note=trim($_POST['nota_publica']??'');$ok=['Recibida','Turnada','Asignada','Reasignada','En revisión','Concluida'];if(in_array($st,$ok,true)){$u=$pdo->prepare("UPDATE denuncias SET estatus=?,nota_publica=?,actualizado_en=NOW() WHERE id=?");$u->execute([$st,$note,$id]);header('Location: detalle.php?id='.$id);exit;}}?><!doctype html><html lang="es"><head><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/estilos.css"><title>Expediente</title></head><body><main class="form"><section class="panel"><h1><?=e($d['folio'])?></h1><?php foreach(['municipio','localidad','tipo_persona','ambito','institucion','persona','clasificacion','relato','evidencia'] as $k):?><p><b><?=e(ucfirst($k))?>:</b> <?=e($d[$k]??'—')?></p><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Actualizar estatus<select name="estatus"><?php foreach(['Recibida','Turnada','Asignada','Reasignada','En revisión','Concluida'] as $st):?><option <?=$d['estatus']===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></label><label>Mensaje para consulta<textarea name="nota_publica"><?=e($d['nota_publica']??'')?></textarea></label><button class="btn">Guardar</button></form><a href="dashboard.php">Volver al panel</a></section></main></body></html>